// Costruisce la richiesta per l'audit del profilo Google Business
const lead = $json;
const LINGUA = 'italiano'; // cambia in 'inglese' se lavori su mercati anglofoni

const system = 'Sei un consulente senior di local SEO specializzato in Google Business Profile per attivita\' locali di servizi (idraulici, HVAC, coperture/tetti, elettricisti, dentisti, tatuatori, autofficine, disinfestazione). Scrivi in ' + LINGUA + ', in modo concreto e azionabile, senza gergo inutile.';

const prompt = `Fai un audit completo del profilo Google Business di questa attivita' locale, basandoti sui dati disponibili:\n\n- Nome: ${lead.name}\n- Categoria: ${lead.category || 'n/d'}\n- Citta'/zona: ${lead.city || lead.address || 'n/d'}\n- Rating: ${lead.rating} stelle\n- Numero recensioni: ${lead.reviews}\n- Sito web: ${lead.site || 'NESSUNO'}\n- Segnali di debolezza rilevati: ${lead.reasons || 'n/d'}\n\nAnalizza: ottimizzazione della categoria, qualita' presumibile delle foto, descrizione dell'attivita', gestione delle recensioni (risposte, velocita', keyword locali), presenza di post/aggiornamenti settimanali, e l'impatto dell'assenza o debolezza del sito web.\n\nStima quanti clienti al mese sta probabilmente perdendo verso competitor con presenza online migliore (i primi 5 risultati su Google Maps catturano ~70% dei click).\n\nProduci: (1) sintesi in 3 righe dei problemi principali, (2) piano di miglioramento passo-passo in ordine di impatto, (3) una stima realistica del valore economico mensile perso. Sii specifico per il settore di questa attivita'.`;

return {
  json: {
    lead,
    anthropic_request: {
      model: 'claude-opus-4-8',
      max_tokens: 4096,
      system,
      messages: [{ role: 'user', content: prompt }],
    },
  },
};

// Estrae l'audit e costruisce la richiesta per l'email a freddo
const auditText = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const lead = $('Prepara audit').item.json.lead;
const LINGUA = 'italiano';
const FIRMA_NOME = 'IL_TUO_NOME';
const FIRMA_ATTIVITA = 'LA_TUA_ATTIVITA';

const system = 'Scrivi email a freddo per attivita\' locali. Suoni come una persona vera che ha guardato davvero il loro profilo Google, MAI come un\'agenzia di marketing. In ' + LINGUA + '. Niente frasi fatte, niente maiuscole urlate, niente emoji.';

const prompt = `Scrivi una email a freddo per questa attivita' locale.\n\nDATI:\n- Attivita': ${lead.name} (${lead.category || 'servizi locali'}) a ${lead.city || lead.address || ''}\n- Rating: ${lead.rating} stelle, ${lead.reviews} recensioni su Google\n- Sito web: ${lead.site || 'nessuno'}\n- Problemi principali dal mio audit: ${auditText.slice(0, 1500)}\n\nREGOLE:\n- Massimo 150 parole nel corpo\n- Cita il loro rating e numero di recensioni REALI\n- Un solo dato concreto su quanti clienti stanno perdendo (dal mio audit)\n- Offri una anteprima GRATUITA del sito gia' costruita per loro (nessun impegno)\n- UNA sola call-to-action chiara (rispondere alla email)\n- Tono: persona vera, diretta, zero marketese\n- Chiudi con la firma: ${FIRMA_NOME}, ${FIRMA_ATTIVITA}\n- Ultima riga (obbligatoria): \"Se preferisci non ricevere altre email da parte mia, rispondi con 'no grazie' e non ti scrivero' piu'.\"\n\nRispondi in JSON con i campi \"subject\" (oggetto breve e specifico, non clickbait) e \"body\".`;

return {
  json: {
    lead,
    audit: auditText,
    anthropic_request: {
      model: 'claude-opus-4-8',
      max_tokens: 1024,
      system,
      messages: [{ role: 'user', content: prompt }],
      output_config: {
        format: {
          type: 'json_schema',
          schema: {
            type: 'object',
            properties: {
              subject: { type: 'string' },
              body: { type: 'string' }
            },
            required: ['subject', 'body'],
            additionalProperties: false
          }
        }
      }
    },
  },
};

// Estrae oggetto e corpo dall'output JSON di Claude
const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const lead = $('Prepara email').item.json.lead;
const audit = $('Prepara email').item.json.audit;

let subject = 'Il profilo Google di ' + lead.name;
let body = text;
try {
  const parsed = JSON.parse(text);
  if (parsed.subject) subject = parsed.subject;
  if (parsed.body) body = parsed.body;
} catch (e) {
  // fallback: usa il testo grezzo
}

return { json: { lead, audit, subject, body } };
